/*
 * A042037  Denominators of continued fraction convergents to sqrt(542).
 * https://oeis.org/A042037
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = denominator of the (n‑th) convergent of the continued
 *            fraction of sqrt(542). Recurrence: q(-1)=0, q(0)=1; for k≥1:
 *            q(k)=c(k)*q(k-1)+q(k-2), where the continued‑fraction
 *            coefficients c(k) are generated by the standard algorithm for
 *            sqrt(542)
 * Range:     u8 n <= 7, u16 n <= 14, u32 n <= 23, u64 n <= 47, u128 n <= 91,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n) {
    /* Special case: first term */
    if (n == 0) return (seq_t)1;

    /* Initial values for continued fraction of sqrt(542) */
    const uint64_t D  = 542ULL;       /* discriminant */
    const uint64_t a0 = 23ULL;        /* floor(sqrt(542)) */

    /* Current denominator sequence */
    seq_t prev = (seq_t)0;            /* q(-1) */
    seq_t curr = (seq_t)1;            /* q(0) */

    /* Variables for CF coefficient generation */
    uint64_t m = 0;                   /* m_0 */
    uint64_t d = 1;                   /* d_0 */
    uint64_t a_coef = a0;             /* a_0, stays constant for a0 itself */

    /* Iterate to compute q(n) */
    for (idx_t i = 1; i <= n; ++i) {
        /* Generate next coefficient a_{i} */
        uint64_t m_next = d * a_coef - m;
        uint64_t d_next = (D - m_next * m_next) / d;
        uint64_t a_next = (a0 + m_next) / d_next;

        /* Compute next denominator: q(i) = a_i * q(i-1) + q(i-2) */
        seq_t tmp = ((seq_t)a_next) * curr;
        seq_t new_curr = tmp + prev;

        /* Shift for next iteration */
        prev = curr;
        curr = new_curr;

        /* Update CF state */
        m = m_next;
        d = d_next;
        a_coef = a_next;
    }

    return curr;
}
